def _neighbor_influence_corr(self, sample_fraction: float = 0.2) -> float:
    if self.N <= 0:
        return 0.0
    sample_size = max(1, int(self.N * sample_fraction))
    indices = self.rng.sample(range(self.N), sample_size) if sample_size < self.N else range(self.N)
    xs, ys = [], []
    for idx in indices:
        p = self.people[idx]
        neigh = p.network_neighbors
        neigh_adopt = sum(1 for j in neigh if self.people[j].current_mask_use) / max(1, len(neigh))
        xs.append(neigh_adopt)
        ys.append(1.0 if p.current_mask_use else 0.0)
    return _pearson_correlation(xs, ys)

def evaluate(self, evaluation_metrics: Optional[List[str]] = None) -> Dict[str, Any]:
    metrics = evaluation_metrics if evaluation_metrics is not None else self.cfg.get("evaluation_metrics", [])
    results: Dict[str, Any] = {}
    adop = self.series.get("adoption_rate", [])
    if not adop:
        return results
    # adoption metrics
    results["adoption_rate_over_time"] = adop if "adoption_rate_over_time" in metrics else None
    # time to thresholds, peak, sustained
    # compliance_by_location_type
    if "compliance_by_location_type" in metrics:
        out = {}
        for k, tot in self.visits_total_by_type.items():
            comp = self.visits_compliant_by_type.get(k, 0)
            out[k] = comp / tot if tot > 0 else None
        results["compliance_by_location_type"] = out
    # equity gap by income decile (top-bottom)
    if "equity_gap_in_adoption" in metrics:
        decs = self._precomputed_deciles or self._income_deciles()
        if len(decs) >= 2:
            def mean_adopt(idx_list):
                return sum(1.0 if self.people[i].current_mask_use else 0.0 for i in idx_list) / len(idx_list)
            results["equity_gap_in_adoption"] = mean_adopt(decs[-1]) - mean_adopt(decs[0])
        else:
            results["equity_gap_in_adoption"] = None
    # inventory outage days
    if "inventory_outage_days" in metrics:
        results["inventory_outage_days"] = sum(self.series.get("any_stockout", []))
    # enforcement actions
    if "enforcement_actions_count" in metrics:
        results["enforcement_actions_count"] = self.enforcement_actions
    # misinformation prevalence
    if "misinformation_prevalence" in metrics:
        results["misinformation_prevalence"] = len(self._misinfo_events) / max(1, len(self.series.get("adoption_rate", [])))
    # cost per additional adopter
    if "cost_per_additional_adopter" in metrics:
        delta = max(0.0, adop[-1] - adop[0])
        results["cost_per_additional_adopter"] = (self.policy_cost_total / delta) if delta > 1e-6 else None
    # epi metrics placeholders if no epi
    if "effective_reproduction_number" in metrics:
        results["effective_reproduction_number"] = None
    if "infection_attack_rate" in metrics:
        results["infection_attack_rate"] = None
    if "cases_averted" in metrics:
        results["cases_averted"] = None
    return results
